#include "qml_app.h"

#include <QQmlEngine>

// Generated by qt_add_qml_module (CMakeLists.txt). fugue_core is a static library without a
// plugin, so nothing else refers to the file that registers the module's types, and the linker
// would leave it out; taking this address keeps it.
extern void qml_register_types_Fugue();

namespace fugue {

void exposeToQml(QQmlEngine &engine, const AppObjects &objects) {
    volatile auto registration = &qml_register_types_Fugue;
    Q_UNUSED(registration);
    auto *app = new QmlApp(objects, &engine);
    if (!engine.setExternalSingletonInstance("Fugue", "App", app))
        qFatal("the Fugue QML module has no App singleton to set");
}

} // namespace fugue
